.sl-faq-grid { background-color: var(--smartlearn-bg); padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 4vw, 2rem); width: 100%; font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-faq-grid .sl-container { max-width: 1200px; margin-inline: auto; }
.sl-faq-grid .sl-header { text-align: center; margin-bottom: clamp(2.5rem, 5vw, 4rem); }
.sl-faq-grid .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.85rem, 3.5vw, 2.5rem); font-weight: 800; color: var(--smartlearn-text); margin-bottom: 1rem; }
.sl-faq-grid .sl-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-faq-grid .sl-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(1.25rem, 3vw, 2rem); }
.sl-faq-grid .sl-card { background: var(--smartlearn-card-bg, transparent); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 12px); padding: clamp(1.5rem, 3vw, 2rem); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); transition: transform 0.3s ease; }
.sl-faq-grid .sl-card:hover { transform: translateY(-4px); }
.sl-faq-grid .sl-icon-wrap { width: 48px; height: 48px; background: rgba(148, 163, 184, 0.12); background: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--smartlearn-primary); margin-bottom: 1.5rem; }
.sl-faq-grid .sl-icon-wrap svg { width: 24px; height: 24px; flex-shrink: 0; }
.sl-faq-grid .sl-q { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.25rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.75rem; }
.sl-faq-grid .sl-a { font-size: 1rem; color: var(--smartlearn-text-muted); line-height: 1.6; margin: 0; }
.sl-faq-grid .sl-a a { color: var(--smartlearn-primary); text-decoration: underline; }
@media (max-width: 767px) { .sl-faq-grid .sl-grid { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .sl-faq-grid .sl-card { transition: none; } .sl-faq-grid .sl-card:hover { transform: none; } }
